        '. Liệt kê 3-5 hook mở đầu và format bài (dạng list, confession, quiz, so sánh...) đang ăn tương tác. Mỗi ý 1 dòng, không chép nguyên văn.',
      { search: true }
    );
  } catch (e) {
    return '';
  }
}

const VOICE = [
